let req = requests
| summarize requests = count(), server_errors = countif(toint(resultCode) >= 500), client_errors = countif(toint(resultCode) between (400 .. 499)), p95_ms = round(percentile(duration, 95), 1);
let exc = exceptions | where client_Type != "Browser" | summarize exceptions = count();
let dep = dependencies | where client_Type != "Browser"
| summarize failed_database_calls = countif(success == false and type contains "postgres");
req | extend key = 1
| join kind=fullouter (exc | extend key = 1) on key
| join kind=fullouter (dep | extend key = 1) on key
| project requests, server_errors, client_errors, p95_ms, exceptions, failed_database_calls

let input = trim(" ", "{TraceOrSpanId}");
let spans = union
(requests | project timestamp, id, parentId = operation_ParentId, operation_Id, service = cloud_RoleName, span_kind = "request", name, detail = url, duration, result = resultCode, failed = (success == false)),
(dependencies | project timestamp, id, parentId = operation_ParentId, operation_Id, service = cloud_RoleName, span_kind = iff(type =="InProc", "internal", type), name, detail = data, duration, result = resultCode, failed = (success == false));
let op = toscalar(spans | where operation_Id == input or id == input | take 1 | project operation_Id);
spans
| where operation_Id == op
| summarize trace_id = take_any(operation_Id), started = min(timestamp), ended = max(timestamp + duration * 1ms), spans = count(), failed_spans = countif(failed), services = strcat_array(make_set(service), ", "), pasted_span = take_anyif(name, id == input)
| project trace_id, started, total_ms = round((ended - started) / 1ms, 2), spans, failed_spans, services, pasted_span

let input = trim(" ", "{TraceOrSpanId}");
let spans = union
(requests | project timestamp, id, parentId = operation_ParentId, operation_Id, service = cloud_RoleName, span_kind = "request", name, detail = url, duration, result = resultCode, failed = (success == false)),
(dependencies | project timestamp, id, parentId = operation_ParentId, operation_Id, service = cloud_RoleName, span_kind = iff(type =="InProc", "internal", type), name, detail = data, duration, result = resultCode, failed = (success == false));
let op = toscalar(spans | where operation_Id == input or id == input | take 1 | project operation_Id);
let start = toscalar(spans | where operation_Id == op | summarize min(timestamp));
let pastedParent = toscalar(spans | where id == input | take 1 | project parentId);
spans
| where operation_Id == op
| extend relation = iff(input == op, "", case(id == input, "pasted", id == pastedParent, "parent", parentId == input, "child", ""))
| project name, service, span_kind, relation, start_ms = round(datetime_diff("microsecond", timestamp, start) / 1000.0, 2), duration_ms = round(duration, 2), result = iff(failed, strcat("failed ", result), result), detail, id, parentId
| order by start_ms asc

let input = trim(" ", "{TraceOrSpanId}");
let spans = union
(requests | project timestamp, id, parentId = operation_ParentId, operation_Id, service = cloud_RoleName, span_kind = "request", name, detail = url, duration, result = resultCode, failed = (success == false)),
(dependencies | project timestamp, id, parentId = operation_ParentId, operation_Id, service = cloud_RoleName, span_kind = iff(type =="InProc", "internal", type), name, detail = data, duration, result = resultCode, failed = (success == false));
let op = toscalar(spans | where operation_Id == input or id == input | take 1 | project operation_Id);
let window = toscalar(spans | where operation_Id == op | summarize s = min(timestamp) - 5m, e = max(timestamp) + 5m | project pack("start", s, "end", e));
customMetrics
| where timestamp between (todatetime(window.start) .. todatetime(window.end))
| where name in ("http.server.request.duration", "db.client.operation.duration", "http.client.request.duration")
| summarize value = sum(valueSum) / sum(valueCount) by series = strcat(cloud_RoleName, ": ", name), bin(timestamp, 1m)
| render timechart

